-- Update only exact starter editorial values. Preserve custom copy and every business/policy field.
CREATE TABLE wonder_before AS SELECT s.value,s.revision,t.value AS es_value,t.source_revision FROM settings s LEFT JOIN content_translations t ON t.entity_type='site' AND t.entity_id='site' AND t.locale='es-MX' WHERE s.key='site';
INSERT INTO content_versions(id,value,actor) SELECT lower(hex(randomblob(16))),value,'system:wonder-positioning' FROM settings WHERE key='site' AND (json_extract(value,'$.headline')='A little mess. A lot of imagination.' OR json_extract(value,'$.intro')='Hands-on arts and crafts for curious kids. Make something special, explore something new, and let creativity lead the way.' OR json_extract(value,'$.about')='Adventure Station brings children together to explore their imagination through seasonal arts and crafts.' OR json_extract(value,'$.promotion')='Make room for a little creativity.');
UPDATE settings SET value=json_set(value,'$.headline',CASE WHEN json_extract(value,'$.headline')='A little mess. A lot of imagination.' THEN 'Big discoveries start with little adventures.' ELSE json_extract(value,'$.headline') END,'$.intro',CASE WHEN json_extract(value,'$.intro')='Hands-on arts and crafts for curious kids. Make something special, explore something new, and let creativity lead the way.' THEN 'Seasonal hands-on experiences where children experiment, imagine, make, discover, and play. Explore creative projects, sensory activities, science-inspired experiments and playful challenges.' ELSE json_extract(value,'$.intro') END,'$.about',CASE WHEN json_extract(value,'$.about')='Adventure Station brings children together to explore their imagination through seasonal arts and crafts.' THEN 'Adventure Station brings Wonder · Create · Play to life through seasonal hands-on experiences for children. An adventure can combine making, discovery and play, with room for different ideas and ways to join in.' ELSE json_extract(value,'$.about') END,'$.promotion',CASE WHEN json_extract(value,'$.promotion')='Make room for a little creativity.' THEN 'Make room for wonder, creativity and play.' ELSE json_extract(value,'$.promotion') END),revision=revision+1 WHERE key='site' AND (json_extract(value,'$.headline')='A little mess. A lot of imagination.' OR json_extract(value,'$.intro')='Hands-on arts and crafts for curious kids. Make something special, explore something new, and let creativity lead the way.' OR json_extract(value,'$.about')='Adventure Station brings children together to explore their imagination through seasonal arts and crafts.' OR json_extract(value,'$.promotion')='Make room for a little creativity.');
INSERT INTO translation_versions(id,entity_type,entity_id,locale,value,source_revision,approved,actor) SELECT lower(hex(randomblob(16))),entity_type,entity_id,locale,value,source_revision,approved,'system:wonder-positioning' FROM content_translations WHERE entity_type='site' AND entity_id='site' AND locale='es-MX';
UPDATE content_translations SET value=json_set(value,'$.headline',CASE WHEN json_extract(value,'$.headline')='Un poco de desorden. Mucha imaginación.' AND json_extract((SELECT value FROM settings WHERE key='site'),'$.headline')='Big discoveries start with little adventures.' THEN 'Los grandes descubrimientos empiezan con pequeñas aventuras.' ELSE json_extract(value,'$.headline') END,'$.intro',CASE WHEN json_extract(value,'$.intro')='Arte y manualidades para peques con curiosidad. Crea algo especial, descubre algo nuevo y deja que la creatividad marque el camino.' AND json_extract((SELECT value FROM settings WHERE key='site'),'$.intro')='Seasonal hands-on experiences where children experiment, imagine, make, discover, and play. Explore creative projects, sensory activities, science-inspired experiments and playful challenges.' THEN 'Experiencias de temporada para experimentar, imaginar, crear, descubrir y jugar. Explora proyectos creativos, actividades sensoriales, experimentos inspirados en la ciencia y retos divertidos.' ELSE json_extract(value,'$.intro') END,'$.about',CASE WHEN json_extract(value,'$.about')='Adventure Station reúne a niñas y niños para explorar su imaginación con arte y manualidades de temporada.' AND json_extract((SELECT value FROM settings WHERE key='site'),'$.about')='Adventure Station brings Wonder · Create · Play to life through seasonal hands-on experiences for children. An adventure can combine making, discovery and play, with room for different ideas and ways to join in.' THEN 'Adventure Station da vida a Wonder · Create · Play con experiencias de temporada para niñas y niños. Una aventura puede combinar creación, descubrimiento y juego, con espacio para distintas ideas y formas de participar.' ELSE json_extract(value,'$.about') END,'$.promotion',CASE WHEN json_extract(value,'$.promotion')='Haz espacio para la creatividad.' AND json_extract((SELECT value FROM settings WHERE key='site'),'$.promotion')='Make room for wonder, creativity and play.' THEN 'Haz espacio para la curiosidad, la creatividad y el juego.' ELSE json_extract(value,'$.promotion') END),source_revision=CASE WHEN EXISTS(SELECT 1 FROM wonder_before b WHERE b.source_revision=b.revision AND (json_extract(b.value,'$.headline')<>'A little mess. A lot of imagination.' OR json_extract(b.es_value,'$.headline')='Un poco de desorden. Mucha imaginación.') AND (json_extract(b.value,'$.intro')<>'Hands-on arts and crafts for curious kids. Make something special, explore something new, and let creativity lead the way.' OR json_extract(b.es_value,'$.intro')='Arte y manualidades para peques con curiosidad. Crea algo especial, descubre algo nuevo y deja que la creatividad marque el camino.') AND (json_extract(b.value,'$.about')<>'Adventure Station brings children together to explore their imagination through seasonal arts and crafts.' OR json_extract(b.es_value,'$.about')='Adventure Station reúne a niñas y niños para explorar su imaginación con arte y manualidades de temporada.') AND (json_extract(b.value,'$.promotion')<>'Make room for a little creativity.' OR json_extract(b.es_value,'$.promotion')='Haz espacio para la creatividad.')) THEN (SELECT revision FROM settings WHERE key='site') ELSE source_revision END,revision=revision+1,updated_at=unixepoch() WHERE entity_type='site' AND entity_id='site' AND locale='es-MX';
DROP TABLE wonder_before;
